/**
 * MaterialIcons with only the glyphs the app uses (#3843): the same
 * `createIconSet` component `@expo/vector-icons/MaterialIcons` builds, over a
 * subset font and glyph map generated by `tools/assets/subset_icon_fonts.py`.
 * `name` accepts only the names in `MATERIAL_ICON_NAMES` (./iconNames.ts).
 */
import createIconSet from "@expo/vector-icons/createIconSet";

import glyphMap from "./MaterialIcons.glyphmap.json";
import type { MaterialIconName } from "./iconNames";

const MaterialIcons = createIconSet(
  glyphMap as Record<MaterialIconName, number>,
  "bc-material-icons",
  // eslint-disable-next-line @typescript-eslint/no-require-imports -- Metro asset: a literal require() is the font's asset id
  require("../../../assets/fonts/MaterialIcons.subset.ttf")
);

export default MaterialIcons;
